<?php $heading_level = isset( $args['heading_level'] ) ? max( 2, min( 6, absint( $args['heading_level'] ) ) ) : 2; ?>
<article <?php post_class( 'blog-card post-card' ); ?>><a class="blog-card-image post-thumb" href="<?php the_permalink(); ?>" aria-hidden="true" tabindex="-1"><?php if ( kimpu_blog_show( 'image' ) && has_post_thumbnail() ) { the_post_thumbnail( 'medium_large', array( 'loading' => 'lazy' ) ); } else { ?><span class="post-thumb placeholder"></span><?php } ?></a><div class="post-content"><h<?php echo esc_attr( $heading_level ); ?>><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h<?php echo esc_attr( $heading_level ); ?>><?php get_template_part( 'template-parts/blog/post-meta' ); ?><?php if ( kimpu_blog_show( 'excerpt' ) ) : ?><p class="blog-card-excerpt"><?php echo esc_html( wp_trim_words( get_the_excerpt(), 26 ) ); ?></p><?php endif; ?><a class="text-link" href="<?php the_permalink(); ?>"><?php esc_html_e( 'Read article', 'kimpu-multipurpose' ); ?> <span aria-hidden="true">→</span></a></div></article>
